
import {
  cmp, File, Content, Folder, Copy, SdkGenError,
  collectDeps, packageVersion, apiName, resolvedFor,
} from '@voxgig/sdkgen'

import { mockRoutes } from './Routes_ts-mock'

import type { Routes, Route, Note } from './Routes_ts-mock'


const SEED_TARGET = 'ts-seed'

// Emitted, not copied: npm leaves a template of this name out of a package.
const GITIGNORE = `node_modules/
dist/
*.tsbuildinfo
`

const HEADER = `// Generated by the ts-mock target of @voxgig/sdkgen-validpack.
// Do not edit: change the API definition or the model, then generate again.
`

const NEEDS_SEED = 'ts-mock needs the ts-seed target, active, in the same project: the mock serves ' +
  'the records the ts-seed library makes, and loads that library from ../ts-seed/dist when it starts. ' +
  'Add it from the project\'s .sdk folder with\n' +
  '  npx voxgig-sdkgen target add @voxgig/sdkgen-validpack/ts-seed\n' +
  'or add the whole pack with `npx voxgig-sdkgen package add @voxgig/sdkgen-validpack`, then generate again.'


function hasSeed(model: any): boolean {
  const seed = model?.main?.kit?.target?.[SEED_TARGET]
  return null != seed && 'object' === typeof seed && false !== seed.active
}


function where(n: Note): string {
  return [n.entity, n.route].filter((part) => null != part && '' !== part).join(' ')
}


function packageJson(model: any, target: any, log: any): string {
  const dev: Record<string, string> = {}
  for (const dep of collectDeps(model, target.name, target.deps, log)) {
    const kinds = String(dep.raw?.kind || '').split(',').map((kind: string) => kind.trim())
    if (kinds.includes('dev')) dev[dep.name] = dep.version
  }

  const name = String(model.name) + '-mock'
  const pkg = {
    name,
    version: packageVersion(model, target.name),
    description: 'A local mock server for the ' + apiName(model) + ' API, serving its seeded test data.',
    private: true,
    type: 'commonjs',
    main: 'dist/index.js',
    types: 'dist/index.d.ts',
    bin: { [name]: 'dist/server.js' },
    files: ['dist', 'src'],
    scripts: {
      build: 'tsc',
      start: 'node dist/server.js',
    },
    license: 'MIT',
    devDependencies: dev,
  }
  return JSON.stringify(pkg, null, 2) + '\n'
}


function routesSource(routes: Routes): string {
  return HEADER + '\n' +
    'import type { Routes } from \'./mock\'\n\n\n' +
    'export const routes: Routes = ' + JSON.stringify(routes, null, 2) + '\n'
}


function answer(route: Route): string {
  const kind = undefined !== route.action ? 'the record it names' :
    'list' === route.op ? 'a list' : 'remove' === route.op && 204 === route.status ? 'nothing' : 'a record'
  return 0 === route.res.length ? kind : kind + ' at `' + ['body', ...route.res].join('.') + '`'
}


function readme(model: any, routes: Routes): string {
  const name = String(model.name) + '-mock'
  const api = apiName(model)
  const base = 'http://127.0.0.1:' + routes.port + routes.prefix

  const rows = routes.routes.map((route) => '| `' + route.method + '` | `' + route.path + '` | `' +
    route.entity + '` | ' + (undefined === route.action ? '`' + route.op + '`' : '`' + route.op +
      '`, action `' + route.action + '`') + ' | ' + route.status + ' | ' + answer(route) + ' |')

  const auth = null == routes.auth ? 'The API declares no security, so no request needs a credential.' :
    'header' === routes.auth.in ?
      'A request needs a credential in the `' + routes.auth.name + '` header' +
      ('' === routes.auth.prefix ? '' : ', after `' + routes.auth.prefix + ' `') +
      ', or the mock answers 401. Any value is accepted unless the mock was given a token.' :
      'A request needs a credential in the `' + routes.auth.name + '` ' + routes.auth.in +
      ', or the mock answers 401. Any value is accepted unless the mock was given a token.'

  const reach = routes.local ?
    'That is the address the definition\'s first server names, so the SDK\'s default base reaches it.' :
    'The SDK\'s default base is not this address: point the SDK at the mock with its `base` option.'

  const notes = routes.notes.map((n) => '- ' + ('' === where(n) ? '' : '`' + where(n) + '`: ') + n.note + '.')

  return `# ${api} mock server

A local HTTP mock of the ${api} API, generated by the \`ts-mock\` target of
\`@voxgig/sdkgen-validpack\`. Do not edit these files: change the API
definition or the model, then generate again.

The mock serves the records of the seed library this project generates in
\`../ts-seed\`. It loads that library from its built output, \`../ts-seed/dist\`,
when it starts, so build the seed library first. The mock runs on
\`node:http\` and has no runtime dependency.


## Use

\`\`\`sh
(cd ../ts-seed && npm install && npm run build)
npm install
npm run build
npm start
\`\`\`

It listens on \`${base}\` by default. ${reach}

| Option | Environment | Sets |
| --- | --- | --- |
| \`--port <n>\` | \`PORT\` | The port: \`0\` takes any free one |
| \`--host <host>\` | \`HOST\` | The host, \`127.0.0.1\` by default |
| \`--seed <seed>\` | | The seed the records are made from |
| \`--count <n>\` | | How many records each entity starts with |
| \`--token <token>\` | | The one credential the mock accepts |

A flag wins over the environment.

\`\`\`ts
import { makeMock } from '${name}'

const mock = makeMock({ seed: 1 })
const server = await mock.listen(0)   // server.url is the base to give the SDK
mock.requests()                       // what the mock was asked, in order
mock.reset({ seed: 2 })               // the store as the seed starts it
await server.close()
\`\`\`


## Routes

| Method | Path | Entity | Operation | Success | Answers |
| --- | --- | --- | --- | --- | --- |
${rows.join('\n')}

Each entity's store starts as the seed library's records. A list holds the
records under the parent its path names, and a query parameter that names a
field keeps the records whose field has that value. A load, update, patch or
remove finds its record by the path's id and parents, or answers 404. A create
takes its id from the seed library's next record number whose id no record
holds, and fills each required field the body leaves out from that record. An update or a patch
merges the body into the record. A field the definition marks read-only, at any
depth, is the mock's to set, and a write-only field is never sent back.

${auth}


## Control

| Route | Does |
| --- | --- |
| \`GET /__health\` | Says the mock is up, with its seed and how many records each entity holds |
| \`POST /__reset\` | Restores the seeded store. The body may set \`seed\`, \`count\` and \`counts\` |
| \`GET /__requests\` | The requests served since the last reset, up to the latest 10,000: number, method, path, query and status |

A recorded request holds no header and no body, and a credential sent in the
query is recorded as \`[redacted]\`.
${0 === notes.length ? '' : '\n\n## Notes\n\n' + notes.join('\n') + '\n'}`
}


const Main = cmp(function Main(props: any) {
  const { target, ctx$ } = props
  const { model, log } = ctx$

  if (!hasSeed(model)) throw new SdkGenError(NEEDS_SEED)

  const routes = mockRoutes(model, resolvedFor(ctx$))

  if ('definition' !== routes.source) {
    log?.warn?.({ point: 'ts-mock-source', target: target.name, note: routes.notes[0]?.note })
  }
  for (const n of routes.notes) {
    log?.info?.({ point: 'ts-mock-note', target: target.name, note: where(n) + ': ' + n.note })
  }

  File({ name: '.gitignore' }, () => Content(GITIGNORE))

  Copy({ from: 'tm/' + target.name })

  File({ name: 'package.json' }, () => Content(packageJson(model, target, log)))
  File({ name: 'README.md' }, () => Content(readme(model, routes)))

  Folder({ name: 'src' }, () => {
    File({ name: 'routes.ts' }, () => Content(routesSource(routes)))
  })
})


export {
  Main,
}
